using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using UnityEditor;using UnityEngine;using MashBoxSDK.AnimationStudio;
public static class StudioPublicationValidation {
 public static void Run(){try{Validate();UnityEditor.EditorApplication.Exit(0);}catch(Exception e){UnityEngine.Debug.LogException(e);UnityEditor.EditorApplication.Exit(1);}}

 static int checks;
 static void Check(bool condition,string message){if(!condition)throw new Exception(message);checks++;}
 static string Vector(Vector4 v)=>string.Join(",",new[]{v.x,v.y,v.z,v.w}.Select(x=>Math.Round(x,5).ToString("F5",System.Globalization.CultureInfo.InvariantCulture)));
 static string[] Canonical(StudioModelDocument.Node node,bool triangles){var mesh=node.mesh;var p=mesh.vertices;var n=mesh.normals;var c=mesh.colors;var uv=new List<Vector4>[8];for(int i=0;i<8;i++){uv[i]=new List<Vector4>();mesh.GetUVs(i,uv[i]);}
 string Vertex(int i){string s=Vector(p[i])+"/"+Vector(n[i]);if(c.Length>0)s+="/"+Vector(c[i]);for(int j=0;j<8;j++)if(uv[j].Count>0)s+="/"+Vector(uv[j][i]);return s;}
 string Face(int sub,IEnumerable<int> indices){var a=indices.Select(Vertex).ToArray();return sub+":"+Enumerable.Range(0,a.Length).Select(i=>string.Join(";",a.Skip(i).Concat(a.Take(i)))).OrderBy(s=>s,StringComparer.Ordinal).First();}
 var result=new List<string>();if(triangles){for(int sub=0;sub<mesh.subMeshCount;sub++){var tr=mesh.GetTriangles(sub);for(int i=0;i<tr.Length;i+=3)result.Add(Face(sub,tr.Skip(i).Take(3)));}}else{var top=new StudioMeshCuts(node);foreach(var face in top.Faces)result.Add(Face(face.Submesh,face.Vertices));}return result.OrderBy(s=>s,StringComparer.Ordinal).ToArray();}
 static void Compare(StudioModelDocument doc,int index,(int,int)[] edges,string label){var holder=new GameObject("Bevel attribute GPU validation");var filter=holder.AddComponent<MeshFilter>();filter.sharedMesh=doc.nodes[index].mesh;try{using(var fast=new StudioMeshToolPreview(doc,new[]{index}))using(var reference=new StudioMeshToolPreview(doc,new[]{index})){
 var a=fast.Targets[0];var b=reference.Targets[0];b.Topology.UseReferenceBevelWriter=true;
 foreach(var setting in new[]{(.1f,0,.53f),(.2f,0,1f),(.7f,0,1f),(.705f,0,1f),(.3f,1,.53f),(.31f,1,1f),(.6f,3,.53f),(.2f,0,1f)}){
 var option=new StudioMeshCuts.BevelOptions{Width=setting.Item1,Subdivisions=setting.Item2,Tension=setting.Item3,Junction=StudioMeshCuts.BevelJunction.Uniform};b.Reset();
 var ra=a.Topology.BevelEdges(a.Work,edges,option);var rb=b.Topology.BevelEdges(b.Work,edges,option);
 var native=UnityEngine.Object.Instantiate(a.Work.mesh);try { native.RecalculateTangents();var actual=a.Work.mesh.tangents;var expected=native.tangents;for(int i=a.Source.tangents.Length==0?0:ra.VertexUpdateStart;i<actual.Length;i++) if((actual[i]-expected[i]).sqrMagnitude>1e-8f)throw new Exception(label+" patch tangent differs from Unity full native at "+i+" "+actual[i]+" "+expected[i]);Check(actual.Length==expected.Length,label+" native patch tangents");} finally {UnityEngine.Object.DestroyImmediate(native);}
 Check(ra.Edges==rb.Edges&&Math.Abs(ra.AppliedWidth-rb.AppliedWidth)<1e-6,label+" width/result");
 Check(Canonical(a.Work,false).SequenceEqual(Canonical(b.Work,false)),label+" polygon/attributes "+setting);
 Check(Canonical(a.Work,true).SequenceEqual(Canonical(b.Work,true)),label+" triangles/attributes "+setting);
 a.VertexUpdate=ra.VertexUpdate; a.VertexUpdateStart=ra.VertexUpdateStart; a.PublishedPositions=ra.PublishedPositions; a.IsBevelPreview=true; fast.Publish(true);a.UseGpuPreview(filter);Check(filter.sharedMesh!=a.Live,label+" GPU mirror attached");if(ra.VertexUpdate!=null){var update=ra.VertexUpdate;for(int stream=0;stream<update.Streams.Length;stream++){using(var buffer=a.RenderMesh.GetVertexBuffer(stream)){var values=new float[update.Streams[stream].Length];buffer.GetData(values,0,update.Start*update.Strides[stream],values.Length);Check(values.SequenceEqual(update.Streams[stream]),label+" GPU attributes match CPU "+setting);}}}Check(Canonical(doc.nodes[index],true).SequenceEqual(Canonical(a.Work,true)),label+" published live streams");
 }
 fast.Restore();Check(filter.sharedMesh==a.Live,label+" cancel restores renderer");Check(a.Live.vertices.SequenceEqual(a.Source.vertices),label+" cancel restores positions");Check(a.Live.triangles.SequenceEqual(a.Source.triangles),label+" cancel restores indices");
 }}finally{UnityEngine.Object.DestroyImmediate(holder);}}
 public static void Validate(){var report=new StringBuilder();try{var doc=ScriptableObject.CreateInstance<StudioModelDocument>();var mesh=StudioModelDocument.BuildPrimitive(PrimitiveType.Cube,out var polygons);doc.nodes.Add(new StudioModelDocument.Node{mesh=mesh,cutPolygons=polygons,cutTriangles=mesh.triangles});var colors=Enumerable.Range(0,mesh.vertexCount).Select(i=>new Color((i%4)/3f,(i%5)/4f,(i%7)/6f,1)).ToList();mesh.SetColors(colors);for(int channel=0;channel<8;channel++){int dimension=2+channel%3;var values=Enumerable.Range(0,mesh.vertexCount).Select(i=>new Vector4((i%4)*.2f,(i/4)*.15f,channel*.1f,i*.03f)).ToList();if(dimension==2)mesh.SetUVs(channel,values.Select(v=>new Vector2(v.x,v.y)).ToList());else if(dimension==3)mesh.SetUVs(channel,values.Select(v=>new Vector3(v.x,v.y,v.z)).ToList());else mesh.SetUVs(channel,values);}var top=new StudioMeshCuts(doc.nodes[0]);var face=top.Faces[0];Compare(doc,0,new[]{(face.Vertices[0],face.Vertices[1])},"cube one edge");var all=new HashSet<(int,int)>();foreach(var f in top.Faces)for(int i=0;i<f.Vertices.Count;i++){int a=f.Vertices[i],b=f.Vertices[(i+1)%f.Vertices.Count];all.Add(a<b?(a,b):(b,a));}Compare(doc,0,all.ToArray(),"cube all edges");UnityEngine.Object.DestroyImmediate(mesh);UnityEngine.Object.DestroyImmediate(doc);
 var model=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/FrameProbe.fbx");var frame=StudioModelDocument.Import(model,"Assets/PublicationFrame.asset");int index=frame.nodes.FindIndex(n=>n.name=="Body"&&n.mesh);var body=frame.nodes[index];top=new StudioMeshCuts(body);var p=body.mesh.vertices;var candidates=new Dictionary<(Vector3,Vector3),List<(int,int,Vector3)>>();foreach(var f in top.Faces){var normal=Vector3.zero;for(int i=1;i+1<f.Vertices.Count;i++)normal+=Vector3.Cross(p[f.Vertices[i]]-p[f.Vertices[0]],p[f.Vertices[i+1]]-p[f.Vertices[0]]);normal.Normalize();for(int i=0;i<f.Vertices.Count;i++){int a=f.Vertices[i],b=f.Vertices[(i+1)%f.Vertices.Count];var key=StudioMeshCuts.NormalEdgePositionKeyForBevel(p[a],p[b]);if(!candidates.TryGetValue(key,out var list))candidates[key]=list=new List<(int,int,Vector3)>();list.Add((a,b,normal));}}
 var sharp=candidates.Where(pair=>pair.Value.Count==2&&Vector3.Dot(pair.Value[0].Item3,pair.Value[1].Item3)<.8f).ToArray();var links=new Dictionary<Vector3,List<int>>();for(int i=0;i<sharp.Length;i++)foreach(var v in new[]{sharp[i].Key.Item1,sharp[i].Key.Item2}){if(!links.TryGetValue(v,out var list))links[v]=list=new List<int>();list.Add(i);}var seen=new HashSet<int>();for(int seed=0;seed<sharp.Length;seed++){if(!seen.Add(seed))continue;var queue=new Queue<int>();queue.Enqueue(seed);var group=new List<int>();bool closed=true;while(queue.Count>0){int i=queue.Dequeue();group.Add(i);foreach(var v in new[]{sharp[i].Key.Item1,sharp[i].Key.Item2}){closed&=links[v].Count==2;foreach(int j in links[v])if(seen.Add(j))queue.Enqueue(j);}}if(closed&&group.Count==40){Compare(frame,index,group.Take(21).Select(i=>(sharp[i].Value[0].Item1,sharp[i].Value[0].Item2)).ToArray(),"frame 21 edges");break;}}
 report.AppendLine("PASS "+checks+" publication equivalence and cancellation assertions");}catch(Exception e){report.AppendLine(e.ToString());throw;}finally{File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"../../publication-validation.txt")),report.ToString());}}
}
